function getType(p){const n=p.name_cn||'',c=p.category; if(c==='沙发')return /模块|组合|转角|贵妃/.test(n)?'sectional':'sofa';if(c==='单椅')return /凳|脚踏|墩/.test(n)?'stool':'lounge';if(c==='餐椅')return'diningchair';if(c==='餐桌'||c==='游戏桌')return'table';if(c==='茶几')return'coffee';if(c==='边几')return'side';if(c==='柜体')return'cabinet';if(c==='灯具')return'lamp';if(c==='地毯')return'rug';if(c==='床')return'bed';if(c==='旱景绿植')return'plant';return'decor';}
