const colorWords=[['墨绿','#294b3d'],['翠绿','#43745b'],['灰绿','#858979'],['苔绿','#758160'],['橄榄','#7d7b4f'],['酒红','#704242'],['深红','#773e37'],['红','#954e42'],['蓝','#435c77'],['青','#477275'],['紫','#817080'],['粉','#c79b93'],['米白','#ded8c8'],['白','#e1dfd6'],['奶油','#e5dec5'],['米','#c9bda4'],['奶咖','#aa9580'],['灰褐','#8e8071'],['灰','#93908a'],['黑','#30302e'],['焦糖','#9c683f'],['棕','#8c6249'],['胡桃','#72523d'],['陶土','#ab6c4e'],['橙','#bf7b3b'],['赭黄','#b28b4e'],['黄','#c3a66a'],['金','#b4a374'],['银','#bcbdb5'],['透明','#d1d9d1']];
function itemColor(p){const s=(p.colors||[]).join(' ')+' '+p.name_cn;return colorWords.find(([k])=>s.includes(k))?.[1]||'#b5a58a';}
function upholsteryPattern(p,m){
 if(!/条纹|千鸟格|棋盘|方格|格纹/.test(p.name_cn))return;
 const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const c=canvas.getContext('2d'),base=itemColor(p),light=new THREE.Color(base).lerp(new THREE.Color('#f0e8d7'),.7).getStyle();c.fillStyle=base;c.fillRect(0,0,128,128);c.fillStyle=light;
 if(/条纹/.test(p.name_cn)){for(let x=0;x<128;x+=16){c.fillRect(x,0,4,128);c.fillRect(x+8,0,1,128);}}
 else{for(let y=0;y<8;y++)for(let x=0;x<8;x++)if((x+y)%2)c.fillRect(x*16,y*16,16,16);}
 const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=texture.wrapT=THREE.RepeatWrapping;texture.repeat.set(2,2);m.color.set('#ffffff');m.map=texture;m.needsUpdate=true;
}
