function roundBox(w,h,d,r=.05){r=Math.min(r,w/3,h/3,d/3);const sh=new THREE.Shape(),x=-w/2+r,y=-h/2+r;sh.moveTo(x,-h/2);sh.lineTo(w/2-r,-h/2);sh.quadraticCurveTo(w/2,-h/2,w/2,y);sh.lineTo(w/2,h/2-r);sh.quadraticCurveTo(w/2,h/2,w/2-r,h/2);sh.lineTo(x,h/2);sh.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);sh.lineTo(-w/2,y);sh.quadraticCurveTo(-w/2,-h/2,x,-h/2);const g=new THREE.ExtrudeGeometry(sh,{depth:Math.max(.004,d-2*r),bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:r*.5,bevelThickness:r,curveSegments:5});g.translate(0,0,-d/2+r);g.computeVertexNormals();return g;}
