 if(type==='sofa'||type==='sectional'){const sw=type==='sectional'?w*.72:w,sd=1;legs(g,sw-.18,sd-.18,.14);box(g,sw,.17,sd,m,0,.22,0,.045);const count=Math.max(2,Math.round(sw/.8));for(let i=0;i<count;i++){box(g,(sw-.25)/count-.025,.20,sd-.23,m,-(sw-.25)/2+(i+.5)*(sw-.25)/count,.40,.04,.07);box(g,(sw-.23)/count-.025,.43,.23,m,-(sw-.23)/2+(i+.5)*(sw-.23)/count,.65,-.37,.07);}for(const x of [-sw/2+.08,sw/2-.08])box(g,.17,.40,sd,m,x,.49,0,.065);if(type==='sectional'){box(g,w-sw+.12,.22,d-.04,m,sw/2+(w-sw)/2-.15,.38,.28,.07);box(g,w-sw+.10,.40,.22,m,sw/2+(w-sw)/2-.15,.65,-.37,.05);legs(g,w-sw-.1,d-.2,.16);}}
 else if(type==='lounge'||type==='diningchair'){const lounge=type==='lounge';legs(g,w*.72,d*.7,lounge?.16:.40);box(g,w*.88,lounge?.23:.13,d*.83,m,0,lounge?.39:.46,.04,.05);box(g,w*.9,lounge?.40:.34,.15,m,0,lounge?.68:.70,-d*.38,.05);if(lounge&&!/无扶手|条纹|软包座|模块/.test(p.name_cn)){box(g,.13,.31,d*.84,m,-w*.43,.54,0,.05);box(g,.13,.31,d*.84,m,w*.43,.54,0,.05);}if(/环/.test(p.name_cn)){g.children.filter(o=>o.position.y>.55).forEach(o=>o.visible=false);const ring=new THREE.Mesh(new THREE.TorusGeometry(w*.43,.065,8,36),m);ring.position.set(0,.65,-d*.12);ring.rotation.x=-.27;g.add(ring);}}
