 const commit=(final=false)=>{clearTimeout(timer);const p=selected();if(!p||(editingId&&editingId!==p.uid))return;const raw=field.value.trim(),number=Number(raw);if(!raw||!Number.isFinite(number)){if(final)renderControls();return;}const value=final?clamp(number/100,min,max):number/100;if(value<min||value>max)return;if(Math.abs(value-p[prop])>.00001){if(!recorded){checkpoint();recorded=true;}p[prop]=value;syncObject(p);updateSelection();persist();requestReflection();}if(final)renderControls();};
